mapper.select:
SELECT p.id AS id, p.payment_no AS paymentNo, p.order_id AS orderId, o.order_name AS orderName, p.amount AS amount, p.payment_time AS paymentTime, p.type AS type, p.status AS status, p.remark AS remark, p.create_time AS createTime FROM ad_payment p LEFT JOIN ad_order o ON o.id = p.order_id AND o.deleted = 0 WHERE p.organization_id = #{request.organizationId} AND p.deleted = 0
AND p.order_id = #{request.orderId}
AND p.status = #{request.status}
AND p.type = #{request.type}
AND (p.payment_no LIKE CONCAT('%', #{request.keyword}, '%') OR o.order_no LIKE CONCAT('%', #{request.keyword}, '%'))
